long long getvl(long long l,long long r,long long x,long long y){
	if(l>=r||x>=y)return 0;
	return vl[psum[r][y]-psum[l][y]-psum[r][x]+psum[l][x]];
}
long long f(long long l,long long r,long long x,long long y){
	long long ans=0,i,c,tl,tr,tx,ty;
	for(i=0;i<16;i++)
	{
		c=0;
		tl=l;
		tr=r;
		tx=x;
		ty=y;
		if(i&1)
		{
			c^=1;
			tl++;
		}
		if(i&2)
