2034H - Rayan vs. Rayaneh Idea and Preparation: MohammadParsaElahimanesh Solution Step 1: According to Bézout's Identity, we can compute $\gcd(x_1, \ldots, x_t)$ and all its multipliers as an integer linear combination of $x_1, x_2, \ldots, x_t$. Step 2: A set {$a_1, \ldots, a_k$} is good (integer linearly independent) if for every $i$, $\gcd(${$a_j \mid j \neq i$}$) \nmid a_i$. Step 3: A set {$a_1, \ldots, a_k$} is good if and only if there exists a set {${p_1}^{q_1}, {p_2}^{q_2}, \ldots, {p_k}^{q_k}$} such that ${p_i}^{q_i} \mid a_j$ for $j \neq i$ and ${p_i}^{q_i} \nmid a_i$. Step 4: The set {$a_1, \ldots, a_k$} can be identified by determining {${p_1}^{q_1}, {p_2}^{q_2}, \ldots, {p_k}^{q_k}$}. Assume $p_1^{q_1} \lt p_2^{q_2} \lt \ldots \lt p_k^{q_k}$, where $p_i \neq p_j$ and $p_i$ is prime. Step 5: Let $G = {p_1}^{q_1} \cdot {p_2}^{q_2} \ldots \cdot {p_k}^{q_k}.$ Then {$a_1, \ldots, a_k$} is good if and only if $\frac{G}{{p_i}^{q_i}} \mid a_i$ and $G \nmid a_i$ for every $i$. Step 6: The answer is a singleton if, for every pair of numbers $x$ and $y$ in the array, $x \mid y$ or $y \mid x$. Since the numbers are distinct, a good subset {$a_1, a_2$} can always be found by searching the first $\log M + 2$ elements. Step 7: Define $CM[i]$ (count multipliers of $i$) as the number of $x$ such that $i \mid a_x$. This can be computed in $O(n + M \log M)$. Step 8: A corresponding set {$a_1, \ldots, a_k$} exists for a set {${p_1}^{q_1}, {p_2}^{q_2}, \ldots, {p_k}^{q_k}$} if and only if $CM\left[\frac{G}{{p_i}^{q_i}}\right] \gt CM[G] \geq 0$ for all $i$. Step 9: Iterate over all valid sets of the form {${p_1}^{q_1}, {p_2}^{q_2}, \ldots, {p_k}^{q_k}$}, and check if a corresponding {$a_1, a_2, \ldots, a_k$} exists. Note that $k \geq 3$ since a good subset {$a_1, a_2$} is found using another method. Step 10: We know $\frac{G}{{p_1}^{q_1}} \leq M$ and also ${p_1}^{q_1} \leq \sqrt{M},$ as ${p_1}^{q_1} \leq \sqrt{{p_2}^{q_2} \cdot {p_3}^{q_3}} \leq \sqrt{\frac{G}{{p_1}^{q_1}}} \leq \sqrt{M}.$ Step 11: There are $\sum_{i=1}^{\frac{\log M}{2}} P[\lfloor \sqrt[2i]{M} \rfloor]$ numbers in the form ${p_1}^{q_1}$, where $P[i]$ denotes the number of primes in the range $[1, i]$. This count is $O(\frac{\sqrt M}{\log M})$. Step 12: The value of $k$ is at most 6 (denoted as $K$), as ${p_2}^{q_2} \ldots {p_k}^{q_k} = \frac{G}{{p_1}^{q_1}} \leq M,$ and $3 \cdot 5 \cdot 7 \cdot 11 \cdot 13 \leq M \lt 3 \cdot 5 \cdot 7 \cdot 11 \cdot 13 \cdot 17.$ Step 13: We can determine {$a_1, \ldots, a_k$} from {${p_1}^{q_1}, {p_2}^{q_2}, \ldots, {p_k}^{q_k}$} in $O(n \cdot K)$. The total time complexity is $O\left(T \cdot M \cdot \frac{\sqrt M}{\log M} \cdot K + T \cdot M \cdot \log M + \sum_{i=0}^T n_i \cdot K\right).$ Implementation

[Reference solution]
/// In the name of God the most beneficent the most merciful

#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops,fast-math,O3")
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

constexpr int T = 100;
constexpr int M = 100001;
constexpr int SQM = 320;
constexpr int LGM = 20;
vector<pair<int,int>> factor;
int t, n[T], count_multipliers[T][M];
bitset<M> is_composite;
vector<int> ans[T], a[T];

inline void calculate_importants() {
    for(int i = 2; i < SQM; i++)
        if(!is_composite[i]) {
            for(int j = i; j < M; j *= i)
                factor.push_back({j,i});
            for(int j = i*i; j < M; j += i)
                is_composite.set(j);
        }
    for(int i = SQM; i < M; i++)
        if(!is_composite[i])
            factor.push_back({i,i});
    sort(factor.begin(), factor.end());
}

void check(vector<int> &factors, int G) {
    if(factors.size() > 2u) {
        for(int i = 0; i < t; i++) 
            if(ans[i].size() < factors.size()) {
                int count_product = (G < M? count_multipliers[i][G] : 0);
                bool can = true;	
                for(auto u: factors)
                    if(count_multipliers[i][G/factor[u].first] == count_product) {
                        can = false;
                        break;
                    }
                if(can)
                    ans[i] = factors;
            }
    }
    int bound = (factors.size() == 1 ? SQM : M);
    if(1LL*G/factor[factors[0]].first*factor[factors.back()].first > bound)
        return;
    for(int new_factor = factors.back(); G/factor[factors[0]].first*factor[new_factor].first <= bound; new_factor++) 
        if(G%factor[new_factor].second) {
            factors.push_back(new_factor);
            check(factors, G*factor[new_factor].first);
            factors.pop_back();
        }
}

int main() {
    ios_base :: sync_with_stdio(false); cin.tie(nullptr);
    calculate_importants();
    cin >> t;
    for(int i = 0; i < t; i++) {
        cin >> n[i];
        a[i].resize(n[i]);
        for(int j = 0; j < n[i]; j++) {
            cin >> a[i][j];
            count_multipliers[i][a[i][j]]++;
        }
        ans[i] = {a[i][0]};
        sort(a[i].begin(), a[i].begin()+min(n[i], LGM));
        for(int c = 0; c+1 < n[i]; c++)
            if(a[i][c+1]%a[i][c]) {
                ans[i] = {a[i][c], a[i][c+1]};
                break;
            }
        for(int c = 1; c < M; c++)
            for(int j = c+c; j < M; j += c)
                count_multipliers[i][c] += count_multipliers[i][j];
    }
    for(int i = 0; factor[i].first < SQM; i++) {
        vector<int> starter = {i};
        check(starter, factor[i].first);
    }
    for(int i = 0; i < t; i++) {
        int k = ans[i].size();
        cout << k << '\n';
        if(k == 1u) {
            cout << ans[i][0] << '\n';
        } else if(k == 2u) {
