#include <bits/stdc++.h>
#define all(s) s.begin(), s.end()
using namespace std;
using ll = long long;
using ull = unsigned long long;

const int _N = 1e5 + 5;

int T;

void solve() {
	ll n, m, k; cin >> n >> m >> k;
	vector<ll> a(n + 1);
	for (int i = 1; i <= n; i++) cin >> a[i];
	vector<ll> kans(m + 1, LLONG_MAX);
	vector<__int128> f(n + 1), g(n + 1), v(n + 1);
	vector<int> vis(n + 1), L(n + 1), L2(n + 1);
	ll sum = 0;
	for (int i = 1; i <= n; i++) sum += a[i];
	__int128 pans = 0;
	for (int i = 1; i <= n; i++) pans += n * a[i] * a[i];
	auto work = [&](ll s) {
		__int128 ans = pans;
		ans += s * s - 2ll * sum * s;
		f.assign(n + 1, LLONG_MAX);
		g.assign(n + 1, LLONG_MAX);
		for (int i = 1; i <= n; i++) {
			v[i] = n * (2 * a[i] * k + k * k) - 2ll * s * k;
			vis[i] = 0;
		}
		for (int i = 1; i <= m; i++) {
			for (int j = 1; j <= n; j++) {
				L[j] = L2[j] = j;
				if (f[j - 1] < 0) f[j] = f[j - 1] + v[j], L[j] = L[j - 1];
				else f[j] = v[j];
				if (!vis[j]) {
					g[j] = LLONG_MAX;
					continue;
				}
				if (g[j - 1] < 0) g[j] = g[j - 1] + 2ll * n * k * k - v[j], L2[j] = L2[j - 1];
				else g[j] = 2ll * n * k * k - v[j];
			}
			__int128 min_sum = LLONG_MAX;
			int l = 1, r = n, type = 0;
			for (int j = 1; j <= n; j++) {
				if (f[j] < min_sum) {
					min_sum = f[j], r = j, l = L[j];
				}
			}
			for (int j = 1; j <= n; j++) {
				if (g[j] < min_sum) {
					min_sum = g[j], r = j, l = L2[j];
					type = 1;
				}
			}
			ans += min_sum;
			if (type == 0) {
				for (int j = l; j <= r; j++) vis[j]++, v[j] += 2 * n * k * k;
			} else {
				for (int j = l; j <= r; j++) vis[j]--, v[j] -= 2 * n * k * k;
			}
			kans[i] = min((__int128)kans[i], ans);
		}
	};

	for (ll x = sum; x <= sum + n * m * k; x += k) {
		work(x);
	}
	for (int i = 1; i <= m; i++) cout << kans[i] << " \n"[i == m];
	return;
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	cin >> T;
	while (T--) {
		solve();
	}
}

Problem B:
[Statement]
[Problem]
Let's say that two strings $a$ and $b$ are equal if you can get the string $b$ by cyclically shifting string $a$. For example, the strings 0100110 and 1100100 are equal, while 1010 and 1100 are not. You are given a binary string $s$ of length $n$. Its first $c$ characters are 1-s, and its last $n - c$ characters are 0-s. In one operation, you can replace one 0 with 1. Calculate the number of unique strings you can get using no more than $k$ operations. Since the answer may be too large, print it modulo $10^9 + 7$.

[Input]
The first and only line contains three integers $n$, $c$ and $k$ ($1 \le n \le 3000$; $1 \le c \le n$; $0 \le k \le n - c$) — the length of string $s$, the length of prefix of 1-s and the maximum number of operations.

[Output]
Print the single integer — the number of unique strings you can achieve performing no more than $k$ operations, modulo $10^9 + 7$.

[Note]
In the first test case, the only possible string is 1. In the second test case, the possible strings are: 100, 110, and 111. String 101 is equal to 110, so we don't count it. In the third test case, the possible strings are: 10000, 11000, 10100. String 10010 is equal to 10100, and 10001 is equal to 11000.

[Samples]
Sample 1 input:
1 1 0
Sample 1 output:

1

Sample 2 input:
3 1 2
Sample 2 output:

3

Sample 3 input:
5 1 1
Sample 3 output:

3

Sample 4 input:
6 2 2
Sample 4 output:

7

Sample 5 input:
24 3 11
Sample 5 output:

498062

[Editorial]
What's common in all strings we can get: each string has no more than $c + k$ ones and at least $c$ consecutive ones. So let's loosen up our constraints a little and just calculate the number of strings with no more than $c + k$ ones and at least $c$ consecutive ones, i. e. this block of ones can be anywhere, can even start at the end and continue at the beginning. Let's name such strings as good strings. Note that the number of unique good strings is exactly equal to the answer of the initial task, since we can shift each good string and make it start from the block of ones. How to calculate the number of good strings? Using Burnside's lemma! Since the group of transformations is just a group of cyclic shifts, we can calculate the answer as following $$\mathrm{ans} = \frac{1}{n} \sum_{i=1}^{n}{\mathrm{FixedPoints}(i)}$$ where $\mathrm{FixedPoints(i)}$ is the number of fixed points, or the number of strings that won't change after a cyclical shift by $i$ characters. Note that if the string doesn't change while shifting by $i$ characters, then it means that $s[p] = s[(p + i) \mod |s|]$ for all $p$. Further investigation reveals that all characters will be split into exactly $g = \gcd(i, n)$ groups and each group will contain exactly $\frac{n}{g}$ equal characters. It means that if $\gcd(i, n) = \gcd(j, n)$ then $\mathrm{FixedPoints}(i) = \mathrm{FixedPoints}(j)$ since in both cases we'll get exactly the same group division. So, we can rewrite the answer as following: $$\mathrm{ans} = \frac{1}{n} \sum_{g | n}{cnt[g] \cdot \mathrm{FixedPoints}(g)}$$ where $cnt[g]$ is the number of cyclic shifts $i$ with $\gcd(i, n) = g$ and can be easily counted. So, it's time to calculate $\mathrm{FixedPoints}(g)$ for some divisor $g$ of $n$. It's not hard to see that if $s[p] = s[(p + g) \mod |s|]$ then the first $g$ characters of $s$ will uniquely define the whole string $s$. So it's enough to work with only a prefix of length $g$, remembering that each character will be copied $\frac{n}{g}$ times. Remember that a good string is a string with at most $c + k$ ones, and since each character will be copied $\frac{n}{g}$ times, we can place at most $on = \frac{(c + k) g}{n}$ ones in our prefix (or at least $zr = g - on$ zeroes). Also, since a good string has $c$ consecutive ones, our prefix should also have $c$ consecutive ones, including the case where the ones go "cyclically" starting at the end of the prefix. In case if $c \ge g$ then the whole prefix should consist of ones, and it's either possible (if $c + k = n$) or impossible (if $c + k \lt n$). In case $c \lt g$ we need to calculate the number of good prefixes that can be described as "the cyclic strings of length $g$ that has no more than $on$ ones and contains $c$ consecutive ones". Instead of good prefixes, let's calculate bad prefixes and subtract them from all possible prefixes. All prefixes are just strings with at most $on$ ones and there are $all = \sum\limits_{i=0}^{on}{\binom{g}{i}}$ such strings. Bad prefixes are cyclic strings with at most $on$ ones, where all blocks of ones have length less than $c$. In order to calculate bad prefixes, let's precalc the following dp: $d[z][l]$ is the number of strings of length $l$ with $z$ zeroes where all blocks of ones have length less than $c$ and the last character of the string is $0$. Why did we use the number of zeroes in the state, and why did we add the last zero in $d[z][l]$? Because it will help us to calculate dp fast. $d[0][0] = 1$. Now, if we have value $d[z][l]$, we can add a block of $i$ ones ($0 \le i \lt c$) and zero to the end of the string and update the value in $d[z + 1][l + i + 1]$. Note that we are updating a segment of row $z + 1$ from $l + 1$ to $l + c$ with value $d[z][l]$ — we can do it in $O(1)$. So, we can precalc the whole dp in $O(n^2)$ time. Now, it's time to calculate the number of bad strings: if we iterate over the length of the prefix of ones, length of the suffix of ones and the number of zeroes in between, we'll get $$bad = \sum_{p=0}^{c - 1}\sum_{s = 0}^{c - p - 1}\sum_{z = zr - 1}^{g - p - s - 1}{d[z][g - p - s - 1]}$$ where $p$ is the number of ones on prefix, $s$ is the number of ones on suffix, and $z$ is the number of zeroes in the "middle part". Since each bad string will look like "($p$ ones)–0–(middle part ending at 0)–($s$ ones)", you can place in the middle part at least $zr - 1$ zeroes and at most $g - p - 1 - s$ zeroes. If we play a little with the sum, we can simplify it in the following way: $$bad = \sum_{p = 0}^{c - 1}\sum_{z = \max(0, zr - 1)}^{g - p - 1}{\mathrm{sumD}(z, g - c, g - p - 1)}$$ where $\mathrm{sumD}(z, g - c, g - p - 1)$ is the sum of dp on the row $z$ from $g - c$ to $g - p - 1$, and you can take it in $O(1)$ if you precalc prefix sums of dp. Good prefixes are just $all - bad$ and since $bad$ can be calculated in $O(g^2)$, the total complexity of $\mathrm{FixedPoints}(g)$ is $O(g^2)$. The resulting complexity is $O(n^2) + \sum\limits_{g|n}{O(g^2)}$ that looks like just $O(n^2)$.

[Reference solution]
#include<bits/stdc++.h>

using namespace std;

#define fore(i, l, r) for(int i = int(l); i < int(r); i++)
#define sz(a) int((a).size())

typedef long long li;
typedef pair<int, int> pt;

template<class A, class B> ostream& operator <<(ostream& out, const pair<A, B> &p) {
    return out << "(" << p.x << ", " << p.y << ")";
}
template<class A> ostream& operator <<(ostream& out, const vector<A> &v) {
    fore(i, 0, sz(v)) {
        if(i) out << " ";
        out << v[i];
    }
    return out;
}

const int MOD = int(1e9) + 7;
int add(int a, int b) {
    a += b;
    while (a >= MOD)
        a -= MOD;
    while (a < 0)
        a += MOD;
    return a;
}
void upd(int &ans, int val) {
    ans = add(ans, val);
}
int mul(int a, int b) {
    return int(a * 1ll * b % MOD);
}
int binPow(int a, int k) {
    int ans = 1;
    while (k > 0) {
        if (k & 1)
            ans = mul(ans, a);
        a = mul(a, a);
        k >>= 1;
    }
    return ans;
}

const int N = 3055;
int f[N], invf[N];

void precalcFact() {
    f[0] = invf[0] = 1;
    fore (i, 1, N) {
        f[i] = mul(f[i - 1], i);
        invf[i] = binPow(f[i], MOD - 2);
    }
}
int C(int n, int k) {
    if (k < 0 || k > n)
        return 0;
    return mul(f[n], mul(invf[k], invf[n - k]));
}

int n, c, k;

inline bool read() {
    if(!(cin >> n >> c >> k))
        return false;
    return true;
}

int d[N][N], sum[N][N];

// d[z][l] - number of strings of length l, with z zeroes and blocks of 1-s shorter than mx
void precalcShort(int mx) {
    memset(d, 0, sizeof d);
    d[0][0] = 1;
    fore (z, 0, n) {
        fore (l, 0, n) {
            if (d[z][l] == 0)
                continue;
            upd(d[z + 1][l + 1], +d[z][l]);
            upd(d[z + 1][min(n, l + mx) + 1], -d[z][l]);
        }
        fore (l, 0, n + 1)
            upd(d[z + 1][l + 1], d[z + 1][l]);
    }

    memset(sum, 0, sizeof sum);
    fore (z, 0, n + 1) fore (l, 0, n + 1)
        sum[z][l + 1] = add(sum[z][l], d[z][l]);

}

//[lf, rg)
int getSum(int z, int lf, int rg) {
    if (z < 0 || z > n || lf >= rg)
        return 0;
    return add(sum[z][rg], -sum[z][lf]);
}

// cnt[g] is a number of x <= n with gcd(x, n) = g
vector<int> precalcCnt(int n) {
    vector<int> cnt(n + 1, 0);
    fore (x, 1, n + 1)
        cnt[gcd(x, n)]++;
    return cnt;
}

int calcFixedPoints(int g) {
    if (c >= g)
        return c + k >= n;

    int cntOnes = (c + k) / (n / g);
    int cntZeros = g - cntOnes;

    int all = 0;
    fore (ones, 0, cntOnes + 1)
        upd(all, C(g, ones));

    int bad = 0;
    fore (pref, 0, c) {
        int minZeros = max(0, cntZeros - 1);
        int minMid = g - c;
        int sufLen = g - pref - 1;
        fore (z, minZeros, sufLen + 1)
            upd(bad, getSum(z, minMid, sufLen + 1));
    }
    return add(all, -bad);
}

inline void solve() {
    precalcFact();
    precalcShort(c);
    auto cnt = precalcCnt(n);

    int ans = 0;
    fore (g, 1, n + 1) {
        if (n % g != 0)
            continue;

        int cntFP = calcFixedPoints(g);
//      cerr << "g = " << g << " += " << cnt[g] << " * " << cntFP << endl;
        upd(ans, mul(cnt[g], cntFP));
    }

//  cerr << "ans/n = " << ans << " " << n << endl;
    cout << mul(ans, binPow(n, MOD - 2)) << endl;
}

int main() {
#ifdef _DEBUG
    freopen("input.txt", "r", stdin);
    int tt = clock();
#endif
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);
    cout << fixed << setprecision(15);

    if(read()) {
        solve();

#ifdef _DEBUG
        cerr << "TIME = " << clock() - tt << endl;
        tt = clock();
#endif
    }
    return 0;
}

Problem A:
[Statement]
[Problem]
Let's define the operation of compressing a string $t$, consisting of at least $2$ digits from $1$ to $9$, as follows: split it into an even number of non-empty substrings — let these substrings be $t_1, t_2, \dots, t_m$ (so, $t = t_1 + t_2 + \dots + t_m$, where $+$ is the concatenation operation); write the string $t_2$ $t_1$ times, then the string $t_4$ $t_3$ times, and so on. For example, for a string "12345", one could do the following: split it into ("1", "23", "4", "5"), and write "235555". Let the function $f(t)$ for a string $t$ return the minimum length of the string that can be obtained as a result of that process. You are given a string $s$, consisting of $n$ digits from $1$ to $9$, and an integer $k$. Calculate the value of the function $f$ for all contiguous substrings of $s$ of length exactly $k$.

[Input]
The first line contains two integers $n$ and $k$ ($2 \le k \le n \le 2 \cdot 10^5$). The second line contains the string $s$ ($|s| = n$), consisting only of digits from $1$ to $9$.

[Output]
Output $n - k + 1$ integers — $f(s_{1,k}), f(s_{2,k+1}), \dots, f(s_{n - k + 1, n})$.

[Samples]
Sample 1 input:
4 4
5999
Sample 1 output:

14 

Sample 2 input:
10 3
1111111111
Sample 2 output:

2 2 2 2 2 2 2 2 

Sample 3 input:
11 4
49998641312
Sample 3 output:

12 18 17 15 12 7 7 2 

[Editorial]
Let's start with learning how to solve the problem for a single string with any polynomial complexity. One immediately wants to use dynamic programming. For example, let $\mathit{dp}_i$ be the minimum length of the compressed string from the first $i$ characters. Then, for the next transition, we could iterate over the next odd block first, and then over the next even block. This results in $O(n^3)$ complexity ($O(n)$ states and $O(n^2)$ for transitions). Note that there is no point in taking very long odd blocks. For instance, we can always take the first digit in the first block and the rest of the string in the second block. In this case, the answer will not exceed $9n$. Therefore, there is no point in taking more than $6$ digits in any odd block, as that would exceed our estimate. Can we take even fewer digits? Ideally, we would like to never take more than $1$ digit. Let's show that this is indeed possible. Consider two blocks: an odd block where we took a number with at least $2$ digits, and the even block after it. Let's try to change them so that the first block consists only of the first digit, and all the others go into the second block. Let's estimate how the length has changed. The digits that were previously in the first block and are now in the second block will now appear in the answer $9$ times in the worst case. The digits in the second block previously appeared $x$ times, and now they appear the following number of times: If the length was $2$, then $\displaystyle \lfloor\frac{x}{10}\rfloor$ times. In the best case, $11 \rightarrow 1$ times, so $-10$. Thus, since the length was $2$, one digit now appears $+9$ times, and at least one appears $-10$ times. The answer has decreased. If the length was $3$, then $\displaystyle \lfloor\frac{x}{100}\rfloor$ times. In the best case, $111 \rightarrow 1$ times, so $-110$. Thus, since the length was $3$, two digits now appear $+9$ times (a total of $+18$), and at least one appears $-110$ times. The answer has decreased. And so on. Now we can write the same dynamic programming in $O(n^2)$. There is no need to iterate over the odd block anymore, as it always has a length of $1$. The iteration over the even block still takes $O(n)$. We can try to make the states of the dp more complicated. What do the transitions look like now? Let $j$ be the end of the even block that we are iterating over. Then $\mathit{dp}_j = \min(\mathit{dp}_j, \mathit{dp}_i + \mathit{ord(s_i)} \cdot (j - i - 1))$. That is, essentially, for each character of the string, we choose how many times it should be written in the answer. Let's put this coefficient (essentially the digit in the last chosen odd block) into the state. Let $\mathit{dp}[i][c]$ be the minimum length of the compressed string from the first $i$ characters, if the last odd block contains the digit $c$. Then the transitions are as follows: $\mathit{dp}[i + 1][c] = \min(\mathit{dp}[i + 1][c], \mathit{dp}[i][c] + c)$ — append the next character to the end of the last even block; $\mathit{dp}[i + 2][s_i] = \min(\mathit{dp}[i + 2][s_i], \mathit{dp}[i][c] + s_i)$ — start a new odd block at position $i$ and immediately take another character in the subsequent even block. If we do not take another character, the dynamic programming will start accumulating empty even blocks, which is prohibited by the problem. Thus, we have learned to solve the problem in $O(n)$ for a fixed string. The remaining task is to figure out how to solve it for all substrings of length $k$. Let's represent the entire set of the query substrings as a queue. That is, to transition from the substring $s_{i,i+k-1}$ to $s_{i+1,i+k}$, we need to append a character to the end and remove a character from the beginning. There is a known technique for solving problems on queues. It is called "minimum on a queue". If we figure out how to solve the problem on a stack (that is, with operations to append a character to the end and remove a character from the end), then we can solve it on a queue using two stacks. Our dynamic programming has only one drawback that slightly hinders this. One transition is at $i + 1$, and the other is at $i + 2$. Let's make both transitions at $i + 1$. To do this, we can introduce a dummy state that indicates that we wrote out an odd block in the last step. That is, let $\mathit{dp}[i][c]$ still mean the same when $c \gt 0$, while the state $c = 0$ is dummy. For convenience, I suggest thinking about these transitions this way. We have a vector of values $\mathit{dp}[i]$ with $10$ elements. We want to be able to convert it into a vector $\mathit{dp}[i + 1]$ with the same $10$ elements, knowing the value of $s_i$. Now, this sounds like multiplying a vector by a matrix. Yes, the matrix consists of operations not $*/+$, but $+/\min$, yet it still works. Then the solution on the stack is as follows. For each digit from $1$ to $9$, we pre-build the transition matrix of dynamic programming for that digit. We maintain one stack of transition matrices and another stack of the dp vectors. When we append a digit, we add elements to both stacks, multiplying the last vector by the matrix. When we remove, we pop the last elements from both stacks. If you are not familiar with the minimum on a queue, you can read this article: https://cp-algorithms.com/data_structures/stack_queue_modification.html. However, we have a slight difference from the standard technique. The minimum is a commutative operation, unlike matrix multiplication. But fixing this is not very difficult. In the first stack, we will multiply by the new matrix on the right. In the second stack, we will multiply on the left. Since the complexity of that queue is linear, we get an algorithm with a complexity of $n \cdot 10^3$. It can be noted that, in the transition matrix, there is a linear number of useful values (not equal to $\infty$). Thus, multiplying by such a matrix can be done in $10^2$.

[Reference solution]
#include <bits/stdc++.h>

#define forn(i, n) for (int i = 0; i < int(n); i++)

using namespace std;

const int D = 10;
const int INF = 1e9;

typedef array<array<int, D>, D> mat;

mat mul(const mat &a, const mat &b, bool fl){
	mat c;
	forn(i, D) forn(j, D) c[i][j] = INF;
	if (fl){
		forn(i, D) forn(j, D){
			c[j][i] = min(c[j][i], min(a[j][0] + b[0][i], a[j][i] + b[i][i]));
			c[j][0] = min(c[j][0], a[j][i] + b[i][0]);
		}
	}
	else{
		forn(i, D) forn(j, D){
			c[i][j] = min(c[i][j], min(a[i][0] + b[0][j], a[i][i] + b[i][j]));
			c[0][j] = min(c[0][j], a[0][i] + b[i][j]);
		}
	}
	return c;
}

struct minqueue{
	vector<pair<mat, mat>> st1, st2;

	void push(const mat &a){
		if (!st1.empty())
			st1.push_back({a, mul(st1.back().second, a, true)});
		else
			st1.push_back({a, a});
	}

	void pop(){
		if (st2.empty()){
			st2 = st1;
			reverse(st2.begin(), st2.end());
			st1.clear();
			assert(!st2.empty());
			st2[0].second = st2[0].first;
			forn(i, int(st2.size()) - 1)
				st2[i + 1].second = mul(st2[i + 1].first, st2[i].second, false);
		}
		st2.pop_back();
	}

	int get(){
