using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Text;
using System.Threading.Tasks;
using TemplateF;

#if !PROBLEM
SolutionF a = new();
a.Solve();
#endif

namespace TemplateF
{
    internal class SolutionF
    {
        private readonly StreamReader sr = new(Console.OpenStandardInput());
        private T Read<T>()
            where T : struct, IConvertible
        {
            char c;
            dynamic res = default(T);
            dynamic sign = 1;
            while (!sr.EndOfStream && char.IsWhiteSpace((char)sr.Peek())) sr.Read();
            if (!sr.EndOfStream && (char)sr.Peek() == '-')
            {
                sr.Read();
                sign = -1;
            }
            while (!sr.EndOfStream && char.IsDigit((char)sr.Peek()))
            {
                c = (char)sr.Read();
                res = res * 10 + c - '0';
            }
            return res * sign;
        }

        private T[] ReadArray<T>(int n)
            where T : struct, IConvertible
        {
            T[] arr = new T[n];
            for (int i = 0; i < n; ++i) arr[i] = Read<T>();
            return arr;
        }

        public void Solve()
        {
            StringBuilder output = new();
            const int maxk = 100000, mod = 998244353, bw = 20;
            List<int>[] d = new List<int>[maxk + 1];
            for (int i = 1; i <= maxk; ++i) d[i] = new() { 1 };
            for (int i = 2; i <= maxk; ++i) {
                for (int j = i; j <= maxk; j += i) d[j].Add(i);
            }
            int[,] dp = new int[bw + 1, maxk + 1], S = new int[bw + 1, maxk + 1];
            for (int k = 1; k <= maxk; ++k) dp[1, k] = S[1, k] = 1;
            for (int i = 2; i <= bw; ++i) {
                for (int j = 1; j <= maxk; ++j) {
                    foreach (var k in d[j]) {
                        dp[i, j] += dp[i - 1, k];
                        dp[i, j] %= mod;
                    }
                    S[i, j] = (S[i - 1, j] + dp[i, j]) % mod;
                }
            }
            int T = Read<int>();
            while (T-- > 0)
            {
                int k = Read<int>(), n = Read<int>();
                if (n <= bw) {
                    for (int j = 1; j <= k; ++j) output.Append(S[n, j]).Append(' ');
                } else {
                    int _k = k;
                    for (k = 1; k <= _k; ++k)  {
                        long ans = 0;
                        for (int i = 1; i <= bw; ++i) {
                            long t = S[i, k];
                            for (int j = 1; j <= bw; ++j) {
                                if (j == i) continue;
                                t *= n - j;
                                t %= mod;
                                t *= Inv((mod + i - j) % mod, mod);
                                t %= mod;
                            }
                            ans = (ans + t) % mod;
                        }
                        output.Append(ans).Append(' ');
                    }
                }
                output.AppendLine();
            }
            Console.Write(output.ToString());
        }
        public static long Inv(long a, long Mod) {
            long u = 0, v = 1, m = Mod;
            while (a > 0) {
                long t = m / a;
                m -= t * a; (a, m) = (m, a);
                u -= t * v; (u, v) = (v, u);
            }
            return (u % Mod + Mod) % Mod;
        }
    }
}

Problem A:
[Statement]
[Problem]
Yarik's birthday is coming soon, and Mark decided to give him an array $a$ of length $n$. Mark knows that Yarik loves bitwise operations very much, and he also has a favorite number $x$, so Mark wants to find the maximum number $k$ such that it is possible to select pairs of numbers [$l_1, r_1$], [$l_2, r_2$], $\ldots$ [$l_k, r_k$], such that: $l_1 = 1$. $r_k = n$. $l_i \le r_i$ for all $i$ from $1$ to $k$. $r_i + 1 = l_{i + 1}$ for all $i$ from $1$ to $k - 1$. $(a_{l_1} \oplus a_{l_1 + 1} \oplus \ldots \oplus a_{r_1}) | (a_{l_2} \oplus a_{l_2 + 1} \oplus \ldots \oplus a_{r_2}) | \ldots | (a_{l_k} \oplus a_{l_k + 1} \oplus \ldots \oplus a_{r_k}) \le x$, where $\oplus$ denotes the operation of bitwise XOR, and $|$ denotes the operation of bitwise OR. If such $k$ does not exist, then output $-1$.

[Input]
Each test consists of multiple test cases. The first line contains a single integer $t$ ($1 \le t \le 10^4$) — the number of test cases. The following lines contain the descriptions of the test cases. The first line of each test case contains two integers $n$ and $x$ ($1 \le n \le 10^5, 0 \le x \lt 2^{30}$) — the length of the array $a$ and the number $x$ respectively. The second line of each test case contains $n$ integers $a_1, a_2, \ldots, a_n$ ($0 \le a_i \lt 2^{30}$) — the array $a$ itself. It is guaranteed that the sum of the values of $n$ across all test cases does not exceed $10^5$.

[Output]
For each test case, output a single integer on a separate line — the maximum suitable number $k$, and $-1$ if such $k$ does not exist.

[Note]
In the first test case, you can take $k$ equal to $2$ and choose two segments [$1, 1$] and [$2, 3$], $(1) | (2 \oplus 3) = 1$. It can be shown that $2$ is the maximum possible answer. In the second test case, the segments [$1, 1$] and [$2, 2$] are suitable, $(1) | (1) = 1$. It is not possible to make more segments. In the third test case, it is not possible to choose $2$ segments, as $(1) | (3) = 3 \gt 2$, so the optimal answer is $1$.

