1975F - Set Idea: Toxel Solution: errorgorn, Toxel Prepared by: Nerovix Hint 1 Consider enumerating each number from $0$ to $n-1$ whether it is contained by $S$, when we have enumerated the first $x$ numbers, there are only $2^{n-x}$ constraints. Solution Read the hints. Consider enumerating each number from $0$ to $n-1$ whether it is contained by $S$. Suppose that the current enumeration reaches $i$, and in the remaining constraints, $T_1$ and $T_2$ are two sets, the only difference between them is whether they contain $i$ ($T_1$ contains $i$): $S$ contains $i$. We can merge $T_1$ and $T_2$ into a new constraint $T'$ and $v_{T'}=(v_{T_1}»1)$&$v_{T_2}$. $S$ doesn't contain $i$. We can merge $T_1$ and $T_2$ into a new constraint $T'$ and $v_{T'}=v_{T_1}$&$v_{T_2}$. We can merge constraints quickly when the enumeration reaches a new number. And the time complexity is $O(n\cdot 2^n)$ Code

[Reference solution]
#include<bits/stdc++.h>

using namespace std;

const int N = 24, S = (1 << 20) + 5;
int n = 0, f[N][S] = {};
vector<int> ans;

inline void dfs(int s = 0, int i = 0){
	if(i < n){
		int m = 1 << (n - i - 1);
		for(int t = 0 ; t < m ; t ++) f[i + 1][t] = f[i][t] & f[i][m | t];
		dfs(s << 1, i + 1);
		for(int t = 0 ; t < m ; t ++) f[i + 1][t] = f[i][t] & (f[i][m | t] >> 1);
		dfs(s << 1 | 1, i + 1);
	}
	else if(f[n][0] & 1) ans.push_back(s);
}

int main(){
	scanf("%d", &n);
	f[0][0] = 1;
	for(int s = 1 ; s < 1 << n ; s ++) scanf("%d", &f[0][s]);
	dfs();
	printf("%d\n", int(ans.size()));
	for(int s : ans) printf("%d\n", s);
	return 0;
}

