[Editorial]
First, if $p_1$ is not equal to $1$, or $s_{m_2}$ is not equal to $n$, or $p_{m_1}$ is not equal to $s_1$, then the answer is $0$ for obvious reasons. Otherwise, we know exactly where the number $n$ is located, at position $s_1$. Next, we have $\binom{n - 1}{s_1 - 1}$ ways to divide the numbers from $1$ to $n - 1$ into two sets — the numbers that will be in the left part and the numbers that will be in the right part (the left part — all indices $ \lt s_1$, the right part — all indices $ \gt s_1$). We solve for the left part, and similarly for the right part. For the left part, the position of the maximum ($p_{m_1 - 1}$) is again defined, and the maximum itself is also unique in the set of numbers for the left part, so we can again divide the left part into two, with $\binom{p_{m_1} - 2}{p_{m_1 - 1} - 1}$ ways to do so, but we can also arrange the numbers between indices $p_{m_1 - 1}$ and $p_{m_1}$ (non-inclusive) in any order, i.e., $(p_{m_1} - p_{m_1 - 1} - 1)!$ ways. Then we solve similarly for the left set (i.e., for indices less than $p_{m_1 - 1}$).

[Reference solution]
#include <bits/stdc++.h>

using i64 = long long;

template<class T>
constexpr T power(T a, i64 b) {
    T res = 1;
    for (; b; b /= 2, a *= a) {
        if (b % 2) {
            res *= a;
        }
    }
    return res;
}

template<int P>
struct MInt {
    int x;
    constexpr MInt() : x{} {}
    constexpr MInt(i64 x) : x{norm(x % P)} {}

    constexpr int norm(int x) const {
        if (x < 0) {
            x += P;
        }
        if (x >= P) {
            x -= P;
        }
        return x;
    }
    constexpr int val() const {
        return x;
    }
    explicit constexpr operator int() const {
        return x;
    }
    constexpr MInt operator-() const {
        MInt res;
        res.x = norm(P - x);
        return res;
    }
    constexpr MInt inv() const {
        assert(x != 0);
        return power(*this, P - 2);
    }
    constexpr MInt &operator*=(MInt rhs) {
        x = 1LL * x * rhs.x % P;
        return *this;
    }
    constexpr MInt &operator+=(MInt rhs) {
        x = norm(x + rhs.x);
        return *this;
    }
    constexpr MInt &operator-=(MInt rhs) {
        x = norm(x - rhs.x);
        return *this;
    }
    constexpr MInt &operator/=(MInt rhs) {
        return *this *= rhs.inv();
    }
    friend constexpr MInt operator*(MInt lhs, MInt rhs) {
        MInt res = lhs;
        res *= rhs;
        return res;
    }
    friend constexpr MInt operator+(MInt lhs, MInt rhs) {
        MInt res = lhs;
        res += rhs;
        return res;
    }
    friend constexpr MInt operator-(MInt lhs, MInt rhs) {
        MInt res = lhs;
        res -= rhs;
        return res;
    }
    friend constexpr MInt operator/(MInt lhs, MInt rhs) {
        MInt res = lhs;
        res /= rhs;
        return res;
    }
    friend constexpr std::istream &operator>>(std::istream &is, MInt &a) {
        i64 v;
        is >> v;
        a = MInt(v);
        return is;
    }
    friend constexpr std::ostream &operator<<(std::ostream &os, const MInt &a) {
        return os << a.val();
    }
    friend constexpr bool operator==(MInt lhs, MInt rhs) {
        return lhs.val() == rhs.val();
    }
    friend constexpr bool operator!=(MInt lhs, MInt rhs) {
        return lhs.val() != rhs.val();
    }
};

constexpr int MOD = 1e9 + 7;
using Z = MInt<MOD>;

namespace comb {
    int n = 0;
    std::vector<Z> _fac = {1};
    std::vector<Z> _invfac = {1};
    std::vector<Z> _inv = {0};

    void init(int m) {
        if (m <= n) return;
        _fac.resize(m + 1);
        _invfac.resize(m + 1);
        _inv.resize(m + 1);

        for (int i = n + 1; i <= m; i++) {
            _fac[i] = _fac[i - 1] * i;
        }
        _invfac[m] = _fac[m].inv();
        for (int i = m; i > n; i--) {
            _invfac[i - 1] = _invfac[i] * i;
            _inv[i] = _invfac[i] * _fac[i - 1];
        }
        n = m;
    }

    Z fac(int m) {
        if (m > n) init(2 * m);
        return _fac[m];
    }
    Z invfac(int m) {
        if (m > n) init(2 * m);
        return _invfac[m];
    }
    Z inv(int m) {
        if (m > n) init(2 * m);
        return _inv[m];
    }
    Z binom(int m, int k) {
        if (m < k || k < 0) return 0;
        return fac(m) * invfac(k) * invfac(m - k);
    }
} // namespace comb

void solve() {
    int n, m1, m2;
    std::cin >> n >> m1 >> m2;
    std::vector<int> p(m1), s(m2);
    for (int i = 0; i < m1; i++) {
        std::cin >> p[i];
    }
    for (int i = 0; i < m2; i++) {
        std::cin >> s[i];
    }
    if (p[0] != 1 || s[0] != p[m1 - 1] || s[m2 - 1] != n) {
        std::cout << "0\n";
        return;
    }
    Z res = comb::binom(n - 1, s[0] - 1);
    for (int i = m1 - 2; i > -1; i--) {
        res *= comb::binom(p[i + 1] - 2, p[i + 1] - p[i] - 1) * comb::fac(p[i + 1] - p[i] - 1);
    }
    for (int i = 1; i < m2; i++) {
        res *= comb::binom(n - s[i - 1] - 1, s[i] - s[i - 1] - 1) * comb::fac(s[i] - s[i - 1] - 1);
    }
    std::cout << res << "\n";
}

