	modint (int x = 0) : v(x) { /* for debug only. assert(0 <= x && x < MOD); */ }
	inline int get() { return v; }
	modint operator - () const { return v ? MOD - v : 0; }
	modint operator + (const modint &k) const { return Modint::add(v, k.v); }
	modint operator - (const modint &k) const { return Modint::sub(v, k.v); }
	modint operator * (const modint &k) const { return Modint::mul(v, k.v); }
	modint operator / (const modint &k) const { return Modint::mul(v, Modint::inv(k.v)); }
	modint pow(const modint &k) const { return Modint::pow(v, k.v); }
	modint inverse() const { return Modint::inv(v); }
	modint operator += (const modint &k) { (v += k.v) >= MOD && (v -= MOD); return *this; }
	modint operator -= (const modint &k) { (v -= k.v) < 0 && (v += MOD); return *this; }
	modint operator *= (const modint &k) { return v = Modint::mul(v, k.v); }
	modint operator /= (const modint &k) { return v = Modint::mul(v, Modint::inv(k.v)); }
};

struct Node {
	int f; modint g; long long len;
	Node () {}
	Node (int F, int G, long long L) : f(F), g(G), len(L) {}
	Node (int F, modint G, long long L) : f(F), g(G), len(L) {}
}; std::deque<Node> Q;

#define MAXN 3000001
int a[MAXN];
void solve() {
	int N = read<int>(); long long p = 0, l = 0, r = 0, v = 0;
	for (int i = 1; i <= N; ++i) p += (a[i] = read<int>());
	for (int i = 1; i <= N; ++i) assert (std::abs(a[i]) <= p);
	Q.clear(); Q.push_back(Node(0, 1, 1)), Q.push_back(Node(1, 1, p));
	modint gv = 1, gz = p % MOD, tv = 0, tz = 0;
	for (int i = 1; i <= N; ++i) if (a[i] >= 0) {
		for (long long ls = a[i]; ls > 0; ) {
			Node k = Q.back(); Q.pop_back();
			if (ls < k.len) Q.push_back(Node(k.f, k.g, k.len - ls)), k.len = ls;
			(k.f == v ? gv : gz) -= k.g * (k.len % MOD), ls -= k.len;
		}
		l += a[i], r = std::min(r + a[i], p);
		if (l > r) ++v, l = a[i], r = p, gv = gz, tv = tz, gz = tz = 0;
		gz += -tz * (a[i] >= MOD ? a[i] - MOD : a[i]);
        if (a[i] > 0) Q.push_front(Node(v + 1, -tz, a[i]));
        tz += gv + tv * ((r - l + 1) % MOD);
	} else if (a[i] < 0) {
		a[i] = -a[i];
		for (long long ls = a[i]; ls > 0; ) {
			Node k = Q.front(); Q.pop_front();
			if (ls < k.len) Q.push_front(Node(k.f, k.g, k.len - ls)), k.len = ls;
			(k.f == v ? gv : gz) -= k.g * (k.len % MOD), ls -= k.len;
		}
		r -= a[i], l = std::max(l - a[i], 0ll);
		if (l > r) ++v, l = 0, r = p - a[i], gv = gz, tv = tz, gz = tz = 0;
		gz += -tz * (a[i] >= MOD ? a[i] - MOD : a[i]), Q.push_back(Node(v + 1, -tz, a[i])), tz += gv + tv * ((r - l + 1) % MOD);
    }
	print<int>((Q.back().g + (r == p ? tv : tz)).get(), '\n');
}
int main() { int T = read<int>(); while (T--) solve(); return 0; }

Problem B:
[Statement]
[Problem]
You are given an array $a$ of $n$ integers. The median of an array $q_1, q_2, \ldots, q_k$ is the number $p_{\lceil \frac{k}{2} \rceil}$, where $p$ is the array $q$ sorted in non-decreasing order. For example, the median of the array $[9, 5, 1, 2, 6]$ is $5$, as in the sorted array $[1, 2, 5, 6, 9]$, the number at index $\lceil \frac{5}{2} \rceil = 3$ is $5$, and the median of the array $[9, 2, 8, 3]$ is $3$, as in the sorted array $[2, 3, 8, 9]$, the number at index $\lceil \frac{4}{2} \rceil = 2$ is $3$. You are allowed to choose an integer $i$ ($1 \le i \le n$) and increase $a_i$ by $1$ in one operation. Your task is to find the minimum number of operations required to increase the median of the array. Note that the array $a$ may not necessarily contain distinct numbers.

[Input]
Each test consists of multiple test cases. The first line contains a single integer $t$ ($1 \le t \le 10^4$) — the number of test cases. Then follows the description of the test cases. The first line of each test case contains a single integer $n$ ($1 \le n \le 10^5$) — the length of the array $a$. The second line of each test case contains $n$ integers $a_1, a_2, \ldots, a_n$ ($1 \le a_i \le 10^9$) — the array $a$. It is guaranteed that the sum of the values of $n$ over all test cases does not exceed $2 \cdot 10^5$.

[Output]
For each test case, output a single integer — the minimum number of operations required to increase the median of the array.

[Note]
In the first test case, you can apply one operation to the first number and obtain the array $[3, 2, 8]$, the median of this array is $3$, as it is the number at index $\lceil \frac{3}{2} \rceil = 2$ in the non-decreasing sorted array $[2, 3, 8]$. The median of the original array $[2, 2, 8]$ is $2$, as it is the number at index $\lceil \frac{3}{2} \rceil = 2$ in the non-decreasing sorted array $[2, 2, 8]$. Thus, the median increased ($3 \gt 2$) in just one operation. In the fourth test case, you can apply one operation to each of the numbers at indices $1, 2, 3$ and obtain the array $[6, 6, 6, 4, 5]$, the median of this array is $6$, as it is the number at index $\lceil \frac{5}{2} \rceil = 3$ in the non-decreasing sorted array $[4, 5, 6, 6, 6]$. The median of the original array $[5, 5, 5, 4, 5]$ is $5$, as it is the number at index $\lceil \frac{5}{2} \rceil = 2$ in the non-decreasing sorted array $[4, 5, 5, 5, 5]$. Thus, the median increased ($6 \gt 5$) in three operations. It can be shown that this is the minimum possible number of operations. In the fifth test case, you can apply one operation to each of the numbers at indices $1, 3$ and obtain the array $[3, 1, 3, 3, 1, 4]$, the median of this array is $3$, as it is the number at index $\lceil \frac{6}{2} \rceil = 3$ in the non-decreasing sorted array $[1, 1, 3, 3, 3, 4]$. The median of the original array $[2, 1, 2, 3, 1, 4]$ is $2$, as it is the number at index $\lceil \frac{6}{2} \rceil = 3$ in the non-decreasing sorted array $[1, 1, 2, 2, 3, 4]$. Thus, the median increased ($3 \gt 2$) in two operations. It can be shown that this is the minimum possible number of operations.

[Samples]
Sample 1 input:
8
3
2 2 8
4
7 3 3 1
1
1000000000
5
5 5 5 4 5
6
2 1 2 3 1 4
2
1 2
2
1 1
4
5 5 5 5
Sample 1 output:

1
2
1
3
2
1
2
3

[Editorial]
The median is defined as the number at index $\lceil \frac{n}{2} \rceil$ in the sorted array, so we can sort the array and work with it. So, let's start by sorting the array and finding the median in it, namely the number $a_{\lceil \frac{n}{2} \rceil}$, let it be equal to $x$. In order for the median to increase, that is, to become at least $x + 1$, it is necessary that there are at least $n - \lceil \frac{n}{2} \rceil + 1$ numbers in the array greater than or equal to $x + 1$. Now let's find the maximum index $t$ such that $a_t$ equals $x$. Then we know that there are currently $n - t$ numbers that are greater than or equal to $x + 1$ (all such $a_i$ that $i \gt t$), which means that at least $(n - \lceil \frac{n}{2} \rceil + 1) - (n - t) = t - \lceil \frac{n}{2} \rceil + 1$ operations will be required. I claim that this estimate is always achievable, it is enough to apply one operation to each index from $\lceil \frac{n}{2} \rceil$ to $t$, because all the numbers under these indices are equal to $x$, so after applying the operations they will become equal to $x + 1$. And in the end, the number of numbers greater than or equal to $x + 1$ will become equal to $(n - t) + (t - \lceil \frac{n}{2} \rceil + 1) = n - \lceil \frac{n}{2} \rceil + 1$, which is what we need.

[Reference solution]
#include <bits/stdc++.h>

using i64 = long long;

void solve() {
    int n;
    std::cin >> n;
    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }
    std::sort(a.begin(), a.end());
    int p = (n + 1) / 2 - 1;
    int res = std::count(a.begin() + p, a.end(), a[p]);
    std::cout << res << "\n";
}

signed main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int t = 1;
    std::cin >> t;

    while (t--) {
        solve();
    }
}

Problem A:
[Statement]
[Problem]
You are given a binary string$^{\dagger}$. Please find the minimum number of pieces you need to cut it into, so that the resulting pieces can be rearranged into a sorted binary string. Note that: each character must lie in exactly one of the pieces; the pieces must be contiguous substrings of the original string; you must use all the pieces in the rearrangement. $^{\dagger}$ A binary string is a string consisting of characters $\texttt{0}$ and $\texttt{1}$. A sorted binary string is a binary string such that all characters $\texttt{0}$ come before all characters $\texttt{1}$.

[Input]
The first line contains a single integer $t$ ($1 \leq t \leq 500$) — the number of test cases. The only line of each test case contains a single string $s$ ($1 \leq |s| \leq 500$) consisting of characters $\texttt{0}$ and $\texttt{1}$, where $|s|$ denotes the length of the string $s$.

[Output]
For each test case, output a single integer — the minimum number of pieces needed to be able to rearrange the string into a sorted binary string.

[Note]
The first test case is pictured in the statement. It can be proven that you can't use fewer than $3$ pieces. In the second and third test cases, the binary string is already sorted, so only $1$ piece is needed. In the fourth test case, you need to make a single cut between the two characters and rearrange them to make the string $\texttt{01}$.

[Samples]
Sample 1 input:
6
11010
00000000
1
10
0001111
0110
Sample 1 output:

3
1
1
2
1
2

[Editorial]
First, note that it's always optimal to divide the string into "blocks" of equal values; there is no use having two strings $\texttt{111}|\texttt{11}$ when we can just have $\texttt{11111}$ and use fewer pieces. Now note that to sort the string, we need all blocks of $\texttt{0}$ to come before all blocks of $\texttt{1}$. The only way that two blocks can join is if we have a block of $\texttt{0}$s before a block of $\texttt{1}$s, and we can have at most one such block. That is, all strings look like: $$(\text{blocks of }\texttt{0}\text{s}) \underbrace{\texttt{0...1}}_{\leq 1\text{joined block of }\texttt{0}\text{s and }\texttt{1}\text{s}} (\text{blocks of }\texttt{1}\text{s})$$ So the answer is the number of blocks, but we should subtract $1$ if a substring $\texttt{01}$ exists (because then we can make the center block above). The time complexity is $\mathcal{O}(|s|)$. For example, for the string $\texttt{111000110}$, we can use three pieces: $\texttt{111}|\texttt{00011}|\texttt{0} \to \texttt{0}|\texttt{00011}|\texttt{111}$.

[Reference solution]
#include <bits/stdc++.h>

using namespace std;

const int MAX = 200'007;
const int MOD = 1'000'000'007;

void solve() {
	string s;
	cin >> s;
	int res = 1;
	bool ex = false;
	for (int i = 0; i + 1 < (int)(s.size()); i++) {
		res += (s[i] != s[i + 1]);
		ex |= (s[i] == '0' && s[i + 1] == '1');
	}
	cout << res - ex << '\n';
}

int main() {
	int tt; cin >> tt; for (int i = 1; i <= tt; i++) {solve();}
	// solve();
}

Problem B:
[Statement]
[Problem]
Define the range of a non-empty array to be the maximum value minus the minimum value. For example, the range of $[1,4,2]$ is $4-1=3$. You are given an array $a_1, a_2, \ldots, a_n$ of length $n \geq 3$. It is guaranteed $a$ is sorted. You have to color each element of $a$ red or blue so that: the range of the red elements does not equal the range of the blue elements, and there is at least one element of each color. If there does not exist any such coloring, you should report it. If there are multiple valid colorings, you can print any of them.

[Input]
The first line contains a single integer $t$ ($1 \leq t \leq 100$) — the number of test cases. The first line of each test case contains an integer $n$ ($3 \leq n \leq 50$) — the length of the array. The second line of each test case contains $n$ integers $a_1, a_2, \ldots, a_n$ ($1 \leq a_i \leq 10^9$). It is guaranteed $a_1 \leq a_2 \leq \ldots \leq a_{n - 1} \leq a_{n}$.

[Output]
For each test case, if it is impossible to color $a$ to satisfy all the constraints, output $\texttt{NO}$. Otherwise, first output $\texttt{YES}$. Then, output a string $s$ of length $n$. For $1 \leq i \leq n$, if you color $a_i$ red, $s_i$ should be $\texttt{R}$. For $1 \leq i \leq n$, if you color $a_i$ blue, $s_i$ should be $\texttt{B}$.

[Note]
In the first test case, given the array $[1, 1, 2, 2]$, we can color the second element blue and the remaining elements red; then the range of the red elements $[1, 2, 2]$ is $2-1=1$, and the range of the blue elements $[1]$ is $1-1=0$. In the second test case, we can color the first, second, fourth and fifth elements $[1, 2, 4, 5]$ blue and the remaining elements $[3]$ red. The range of the red elements is $3 - 3 = 0$ and the range of the blue elements is $5 - 1 = 4$, which are different. In the third test case, it can be shown there is no way to color $a = [3, 3, 3]$ to satisfy the constraints.

