    while(tt--)
    {
        int n;
        cin>>n;
        vector<vector<long long>>v(3,vector<long long>(n+1,0));
        for(int i=0;i<3;i++){
            for(int j=1;j<=n;j++){
                cin>>v[i][j];
            }
        }
        for(int i=0;i<3;i++){
            for(int j=1;j<=n;j++){
                v[i][j]+=v[i][j-1];
            }
        }

        long long tot= (v[0][n]+2)/3;

        vector<vector<int>>ans(3,vector<int>(2,0));


        int f=0;
        for(int i=0;i<3;i++){
            if(f)break;
            for(int j=0;j<3;j++){
                if(f)break;
                if(j==i)continue;
                for(int k=0;k<3;k++){
                    if(f)break;
                    if(k==j || k==i)continue;
                    // cerr<<i<<j<<k<<'\n';
                    for(int x=1;x<=n;x++){
                        if(f)break;
                            auto it = lower_bound(all(v[j]),tot+v[j][x])-v[j].begin();

                            if(it<n){
                                ll sm2 = v[j][it]-v[j][x];
                                ll sm3 = v[k][n]-v[k][it];
                                if(v[i][x]>=tot && sm2 >=tot && sm3>=tot){
                                    ans[i][0]=1;ans[i][1]=x;
                                    ans[j][0]=x+1;ans[j][1]=it;
                                    ans[k][0]=it+1;ans[k][1]=n;
                                    f=1;
                                }
                            }

                    }
