[Editorial]
1993F2 - Dyn-scripted Robot (Hard Version) Solution The idea of this version is almost the same as F1: counting the number of pairs $(i, j)$ that satisfies: $ix_n + x_j\equiv 0\pmod{2W}$, and $iy_n + y_j\equiv 0\pmod{2H}$ However, as $k$ is increased to $10^{12}$ we cannot brute-force the same way as the previous version. Luckily, there is a more efficient way. We need to modify these equivalences a bit: $ix_n \equiv -x_j\pmod{2W}$ $(*)$ $iy_n \equiv -y_j\pmod{2H}$ As we can see, these two equivalences have the same format $ia \equiv b\pmod{M}$. To solve this equivalence for $i$, one way to hang around is to divide $a$, $b$ and $M$ by $\gcd(a, M)$. If $b$ is not divisible, there is no solution! Otherwise, we come up with: $i \equiv ba^{-1}\pmod{M}$ Where $a^{-1}$ is the modular inverse of $a$. We can always calculate it because the condition $\gcd(a, M)=1$ is satisfied. Let's define $g=\gcd(2W, x_n)$, $c_x = -\frac{x_j}g\left(\frac{x_n}g\right)^{-1}$ and $W'=\frac{2W}{g}$ (similar for $c_y$ and $H'$). Then, the solutions of the equivalences at $(*)$ are: $i\equiv c_x\pmod{W'}$ $i\equiv c_y\pmod{H'}$ This system of equivalences can be solved using Chinese Remainder Theorem. After some calculations, we come up with: $i=c_x + zW'$ ($z$ is a non-negative integer). $zW'\equiv c_y-c_x\pmod{H'}$ $(**)$ $(**)$ can be solved for $z$ the same way as $(*)$. Now we know the solution is $i \equiv c_x + zW' \pmod{lcm(W', H')}$, the last thing to do is to count number of such value doesn't exceed $k-1$ and we're done! Time complexity: $O(Nlog(W))$ Code (C++)

[Reference solution]
#include <bits/stdc++.h>
using namespace std;


using ll = long long;

namespace CRT {    
    // v * inv(v, M) = 1 (mod M)
    ll inv(ll v, ll M) {
        ll a = 1, b = 0;
        for (ll x = v, y = M; x != 0; ) {
            swap(a, b -= y/x * a);
            swap(x, y -= y/x * x);
        }
        return b + (b<0) * M;
    }

    // Minimum x that ax = b (mod c)
    ll solve_1(ll a, ll b, ll c) {
        ll g = gcd(a, c);
        if (b % g != 0) return -1;
        return b/g * inv(a/g, c/g) % (c/g);
    }

    // Minimum x that x%b = a and x%d = c
    ll solve_2(ll a, ll b, ll c, ll d) {
        ll t = (c-a)%d;
        if (t < 0) t += d;
        ll k = solve_1(b, t, d);
        return k==-1 ? -1 : a + k*b;
    }
}


const int N = 1e6 + 5;

ll n, k, w, h;
ll x[N], y[N];

int main() {
    cin.tie(nullptr) -> sync_with_stdio(false);

    int tc; cin >> tc;
    while (tc--) {
        string s;
        cin >> n >> k >> w >> h >> s;

        for (int i = 1; i <= n; i++) {
            x[i] = x[i-1] + (s[i-1] == 'R') - (s[i-1] == 'L');
            y[i] = y[i-1] + (s[i-1] == 'U') - (s[i-1] == 'D');
            x[i] += (x[i] < 0) * 2*w - (x[i] >= 2*w) * 2*w;
            y[i] += (y[i] < 0) * 2*h - (y[i] >= 2*h) * 2*h;
        }

        ll ww = 2*w / gcd(x[n], 2*w);
        ll hh = 2*h / gcd(y[n], 2*h);
        ll ans = 0, l = lcm(ww, hh);

        for (int i = 1; i <= n; i++) {
            ll cx = CRT::solve_1(x[n], 2*w - x[i], 2*w);
            ll cy = CRT::solve_1(y[n], 2*h - y[i], 2*h);
            if (cx == -1 || cy == -1) continue;

            ll result = CRT::solve_2(cx, ww, cy, hh);
            if (result != -1 && result < k) {
                ans += (k - result - 1) / l + 1;
            }
        }

        cout << ans << '\n';
    }
}

