#pragma GCC optimize("Ofast")

#include <bits/stdc++.h>   
#include <ext/pb_ds/tree_policy.hpp>
#include <ext/pb_ds/assoc_container.hpp>
using namespace __gnu_pbds;   
using namespace std;
#define ll long long
#define ld long double
#define nline "\n"
#define f first
#define s second
#define sz(x) (ll)x.size()
#define vl vector<ll>
const ll INF_MUL=1e13;
const ll INF_ADD=1e18;
#define all(x) x.begin(),x.end()
mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
typedef tree<ll, null_type, less<ll>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;
//--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------     
const ll MOD=998244353;
const ll MAX=500500;
vector<ll> fact(MAX+2,1),inv_fact(MAX+2,1);
ll binpow(ll a,ll b,ll MOD){
    ll ans=1;
    a%=MOD;  
    while(b){
        if(b&1)
            ans=(ans*a)%MOD;
        b/=2;
        a=(a*a)%MOD;
    }
    return ans;
}
ll inverse(ll a,ll MOD){
    return binpow(a,MOD-2,MOD);
} 
void precompute(ll MOD){
    for(ll i=2;i<MAX;i++){
        fact[i]=(fact[i-1]*i)%MOD;
    }
    inv_fact[MAX-1]=inverse(fact[MAX-1],MOD);
    for(ll i=MAX-2;i>=0;i--){
        inv_fact[i]=(inv_fact[i+1]*(i+1))%MOD;
    }
}
ll nCr(ll a,ll b,ll MOD){
    if((a<0)||(a<b)||(b<0))
        return 0;   
    ll denom=(inv_fact[b]*inv_fact[a-b])%MOD;
    return (denom*fact[a])%MOD;  
}
ll l[MAX],r[MAX],lft[MAX],rght[MAX],power[MAX];
void solve(){ 
  ll n; cin>>n;
  power[0]=1;
  for(ll i=1;i<=n;i++){
    cin>>l[i]>>r[i];
    power[i]=(power[i-1]*2ll)%MOD;
  }
  for(ll i=1;i<=n;i++){
    lft[i]=rght[i]=0;
    for(ll j=1;j<=n;j++){
      if(make_pair(r[i],i)>make_pair(r[j],j)){
        lft[i]++;
      }
      if(make_pair(l[i],i)<make_pair(l[j],j)){
        rght[i]++;
      }
    }
  }
  ll ans=0;
  for(ll i=1;i<=n;i++){
    for(ll j=1;j<=n;j++){
      if(r[i]<l[j]){
        ll found=lft[i]+rght[j];
        ll now=nCr(found,lft[i],MOD)*(l[j]-r[i]);
        now%=MOD;
        ll remaining=n-found-2;
        ans=(ans+now*power[remaining])%MOD;
      }
    }
  }
  cout<<ans<<nline;
  return;    
}  
int main()                                                                                 
{         
  ios_base::sync_with_stdio(false);                         
  cin.tie(NULL);                              
  ll test_cases=1;                 
  cin>>test_cases;
  precompute(MOD);
  while(test_cases--){
    solve();
  }
  cout<<fixed<<setprecision(12);  
  cerr<<"Time:"<<1000*((double)clock())/(double)CLOCKS_PER_SEC<<"ms\n"; 
}

Problem B:
[Statement]
[Problem]
There are $n$ flowers in a row, the $i$-th of them initially has a positive height of $h_i$ meters. Every second, the wind will blow from the left, causing the height of some flowers to decrease. Specifically, every second, for each $i$ from $1$ to $n$, in this order, the following happens: If $i = n$ or $h_i \gt h_{i + 1}$, the value of $h_i$ changes to $\max(0, h_i - 1)$. How many seconds will pass before $h_i=0$ for all $1 \le i \le n$ for the first time?

[Input]
Each test contains multiple test cases. The first line of input contains a single integer $t$ ($1 \le t \le 10^4$) — the number of test cases. The description of the test cases follows. The first line of each test case contains a single integer $n$ ($1 \le n \le 10^5$) — the number of flowers. The second line of each test case contains $n$ integers $h_1, h_2, \ldots, h_n$ ($1 \le h_i \le 10 ^ 9$) — the heights of the flowers. It is guaranteed that the sum of $n$ over all test cases does not exceed $10^5$.

[Output]
For each test case, output a single integer — the number of seconds that will pass before $h_i=0$ for all $1 \le i \le n$.

[Note]
In the first test case, the flower heights change as follows: $[1, 1, 2] \rightarrow [1, 1, 1] \rightarrow [1, 1, 0] \rightarrow [1, 0, 0] \rightarrow [0, 0, 0]$. In the second test case, the flower heights change as follows: $[3, 1] \rightarrow [2, 0] \rightarrow [1, 0] \rightarrow [0, 0]$.

[Samples]
Sample 1 input:
4
3
1 1 2
2
3 1
1
9
5
7 4 4 3 2
Sample 1 output:

4
3
9
7

[Editorial]
First, let's try to find when $h_{n}$ will first be equal to zero. The answer is clearly $h_{n}$. Suppose for some $2 \le i \le n$ we know that $h_{i}$ will first become equal to zero at time $t_{i}$ ($t_n = h_n$). If at some point in time, $h_{i-1}$ was equal to $h_{i}$ (at the start of the second and before they are both equal to zero), $t_{i-1}$ is equal to $t_{i} + 1$. Since after that point in time, if $h_{i}$ decreases, $h_{i-1}$ must decrease in the next second. If $h_{i-1}$ is never equal to $h_{i}$ (until they hit zero), $h_{i - 1}$ must always be strictly greater than $h_{i}$. This means that $h_{i-1}$ will keep decreasing every second until it hits zero, so $t_{i-1}$ is equal to $h_{i-1}$ in this case. Examples: The array $[2, 3, 1, 1, 1]$ changes as follows: $[2, \color{red}{3}, 1, 1, \color{red}{1}] \rightarrow [2, \color{red}{2}, 1, \color{red}{1}, 0] \rightarrow [\color{red}{2}, 1, \color{red}{1}, 0, 0] \rightarrow$ $[1, \color{red}{1}, 0, 0, 0] \rightarrow [\color{red}{1}, 0, 0, 0, 0] \rightarrow [0, 0, 0, 0, 0]$. If we focus on the first two elements, they change as follows: $[2, \color{red}{3}] \rightarrow [2, \color{red}{2}] \rightarrow [\color{red}{2}, 1] \rightarrow [1, 1] \rightarrow [1, \color{red}{1}] \rightarrow [\color{red}{1}, 0] \rightarrow [0, 0]$. The array $[4, 1, 1]$ changes as follows: $[\color{red}{4}, 1, \color{red}{1}] \rightarrow [\color{red}{3}, \color{red}{1}, 0] \rightarrow [\color{red}{2}, 0, 0] \rightarrow [\color{red}{1}, 0, 0] \rightarrow [0, 0, 0]$. Let's combine the two cases. If initially $h_{i-1} \le h_{i}$ holds, $h_{i-1}$ will become equal to $h_{i}$ at some point in time, so $t_{i-1} = t_{i} + 1$. Else, $h_{i-1} \gt h_{i}$, so $t_{i-1} = h_{i-1}$. Combining the two, we get $t_{i-1} = \max(h_{i-1}, t_{i} + 1)$. Since we know $t_n = h_n$, we can easily calculate all the other values of $t_i$ by iterating from $n - 1$ to $1$. The answer to the problem is $t_1$, since $t_{i-1} \ge t_{i} + 1$ for all $2 \le i \le n$. Complexity: $\mathcal{O}(n)$

