void solve() {
    int n;
    cin >> n;

    vector<int> h(n);
    for (auto &x: h) cin >> x;

    int ans = h[n - 1];
    for (int i = n - 2; i >= 0; i--) {
        ans = max(ans + 1, h[i]);
    }

    cout << ans << nl;
}

