using ll = long long;
using vll = vector <ll>;
using ii = pair <ll, ll>;
using vii = vector <ii>;

void tc () {
    ll n, k;
    cin >> n >> k;
    vll ve(n);
    for (ll &i : ve) cin >> i;
    vll th(k+1, 0);
    for (ll i : ve) {
        if (i >= k) continue;
        th[i]++;
    }
