    for (ll i = 1; i < k; i++) {
        if (i == k-i) {
            ans += th[i]/2;
            continue;
        }
        ll minN = min(th[i], th[k-i]);
        th[i] -= minN;
        th[k-i] -= minN;
        ans += minN;
    }
    cout << ans << '\n';
}

