#include <bits/stdc++.h>
using namespace std;
void solve()
{
    int n;
    cin>>n;
    vector<string>cad(n);
    vector<vector<int> >vot(2,vector<int>(n+8));
    for(int k=0;k<2;k++)
    {
	cin>>cad[k];
	for(int i=0;i<n;i++)
		if(cad[k][i]=='A')
			vot[k][i+1]=1;
    }
    vector<vector<int> >dp(n+9,vector<int>(3,-1));
    dp[0][0]=0;
    for(int k=0;k<=n-1;k++)
    {
	for(int i=0;i<3;i++)
	{
	    if(dp[k][i]!=-1)
	    {
	   	int vt=0,val=dp[k][i];
	  	    if(i==0)
		    {
			// *
			// *
			vt=(vot[0][k+1]+vot[0][k+2]+vot[0][k+3])/2+(vot[1][k+1]+vot[1][k+2]+vot[1][k+3])/2;
			dp[k+3][0]=max(vt+val,dp[k+3][0]);
			vt=(vot[1][k+1]+vot[0][k+2]+vot[0][k+1])/2;
			dp[k+1][1]=max(vt+val,dp[k+1][1]);
			vt=(vot[1][k+1]+vot[1][k+2]+vot[0][k+1])/2;
			dp[k+1][2]=max(vt+val,dp[k+1][2]);
		    }
		    if(i==1)
		    {
			// **
			// *
			vt=(vot[0][k+2]+vot[0][k+3]+vot[0][k+4])/2+(vot[1][k+1]+vot[1][k+2]+vot[1][k+3])/2;
			dp[k+3][1]=max(vt+val,dp[k+3][1]);
			vt=(vot[1][k+1]+vot[1][k+2]+vot[0][k+2])/2;
			dp[k+2][0]=max(vt+val,dp[k+2][0]);
	   	    }
		    if(i==2)
		    {
			//*
			//**
			vt=(vot[1][k+2]+vot[1][k+3]+vot[1][k+4])/2+(vot[0][k+1]+vot[0][k+2]+vot[0][k+3])/2;
			dp[k+3][2]=max(vt+val,dp[k+3][2]);
			vt=(vot[0][k+1]+vot[0][k+2]+vot[1][k+2])/2;
			dp[k+2][0]=max(vt+val,dp[k+2][0]);
		    }
	    }
	}
    }
    cout<<dp[n][0]<<endl;
}
int main() {
    int t;
    cin>>t;
    while(t--)
	solve();
}

Problem B:
[Statement]
[Problem]
Yaroslav is playing a computer game, and at one of the levels, he encountered $n$ mushrooms arranged in a row. Each mushroom has its own level of toxicity; the $i$-th mushroom from the beginning has a toxicity level of $a_i$. Yaroslav can choose two integers $1 \le l \le r \le n$, and then his character will take turns from left to right to eat mushrooms from this subsegment one by one, i.e., the mushrooms with numbers $l, l+1, l+2, \ldots, r$. The character has a toxicity level $g$, initially equal to $0$. The computer game is defined by the number $x$ — the maximum toxicity level at any given time. When eating a mushroom with toxicity level $k$, the following happens: The toxicity level of the character is increased by $k$. If $g \leq x$, the process continues; otherwise, $g$ becomes zero and the process continues. Yaroslav became interested in how many ways there are to choose the values of $l$ and $r$ such that the final value of $g$ is not zero. Help Yaroslav find this number!

[Input]
Each test consists of multiple test cases. The first line contains an integer $t$ ($1 \le t \le 10^{4}$) — the number of test cases. Then follows the description of the test cases. The first line of each test case contains two integers $n$, $x$ ($1 \leq n \leq 2 \cdot 10^5, 1 \le x \le 10^9$) — the number of mushrooms and the maximum toxicity level. The second line of each test case contains $n$ numbers $a_1, a_2, \ldots, a_n$ ($1 \leq a_i \leq 10^9$). It is guaranteed that the sum of $n$ over all test cases does not exceed $2 \cdot 10^5$.

[Output]
For each test case, output a single number — the number of subsegments such that the final value of $g$ will not be zero.

[Note]
In the first test case, the subsegments $(1, 1)$, $(1, 2)$, $(1, 4)$, $(2, 2)$, $(2, 3)$, $(3, 3)$, $(3, 4)$ and $(4, 4)$ are suitable. In the second test case, non-zero $g$ will remain only on the subsegments $(1, 1)$ and $(2, 2)$. In the third test case, on the only possible subsegment, $g$ will be zero.

[Samples]
Sample 1 input:
5
4 2
1 1 1 1
3 2
1 2 3
1 6
10
6 3
1 2 1 4 3 8
5 999999999
999999999 999999998 1000000000 1000000000 500000000
Sample 1 output:

8
2
0
10
7

[Editorial]
We'll solve the problem by dynamic programming. Let $dp[i]$ — the number of good subsegments with left boundary at $i$. We will count $dp$ from the end, for each $i$ we will find such a minimum $j$ that the sum on the subsegment $[i; j]$ is greater than $x$. If there is no such $j$, then all right bounds are good, otherwise $dp[i] = dp[j + 1] + j - i$. To search for $j$, we can use a binary search on prefix sums. The answer will be the sum of all $dp$.

[Reference solution]
#include<bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);

    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        ll x;
        cin >> n >> x;
        vector<ll> a(n + 1);
        for (int i = 1; i <= n; ++i) cin >> a[i];
        partial_sum(a.begin() + 1, a.end(), a.begin() + 1);
        vector<int> dp(n + 2);
        for (int i = n - 1; i >= 0; --i) {
            int q = upper_bound(a.begin(), a.end(), a[i] + x) - a.begin();
            dp[i] = dp[q] + q - i - 1;
        }
        cout << accumulate(dp.begin(), dp.end(), 0ll) << '\n';
    }
}

Problem A:
[Statement]
[Problem]
A newly discovered organism can be represented as a set of cells on an infinite grid. There is a coordinate system on the grid such that each cell has two integer coordinates $x$ and $y$. A cell with coordinates $x=a$ and $y=b$ will be denoted as $(a, b)$. Initially, the organism consists of a single cell $(0, 0)$. Then zero or more divisions can happen. In one division, a cell $(a, b)$ is removed and replaced by two cells $(a+1, b)$ and $(a, b+1)$. For example, after the first division, the organism always consists of two cells $(1, 0)$ and $(0, 1)$, and after the second division, it is either the three cells $(2, 0)$, $(1, 1)$ and $(0, 1)$, or the three cells $(1, 0)$, $(1, 1)$ and $(0, 2)$. A division of a cell $(a, b)$ can only happen if the cells $(a+1, b)$ and $(a, b+1)$ are not yet part of the organism. For example, the cell $(1, 0)$ cannot divide if the organism currently consists of the three cells $(1, 0)$, $(1, 1)$ and $(0, 2)$, since the cell $(1, 1)$ that would be one of the results of this division is already part of the organism. You are given a set of forbidden cells ${(c_i, d_i)}$. Is it possible for the organism to contain none of those cells after zero or more divisions?

[Input]
Each test contains multiple test cases. The first line contains an integer $t$ ($1 \le t \le 10\,000$) — the number of test cases. The descriptions of the $t$ test cases follow. The first line of each test case contains an integer $n$ ($1 \le n \le 10^6$) — the number of forbidden cells. The next $n$ lines contain two integers each. The $i$-th of such lines contains $c_i$ and $d_i$ ($0 \le c_i, d_i \le 10^9$) — the coordinates of the $i$-th forbidden cell. It is guaranteed that all forbidden cells are distinct. It is guaranteed that the sum of values of $n$ over all test cases does not exceed $10^6$.

[Output]
For each test case, print $\texttt{YES}$ if it is possible for the organism to contain no forbidden cells after zero or more divisions. Otherwise, print $\texttt{NO}$.

[Note]
In the first test case, dividing the following cells in the following order creates an organism without any forbidden cells: $(0, 0)$, $(1, 0)$, $(1, 1)$, $(0, 1)$, $(2, 1)$, $(2, 2)$, $(1, 2)$, $(1, 1)$. The following picture demonstrates how the organism changes during this process: In the second test case, you can see that, surprisingly, any organism always has at least one cell in the $0 \le x, y \le 3$ square, no matter how many divisions we do.

